import { readFileSync, writeFileSync } from 'node:fs';
import { performance } from 'node:perf_hooks';
import { createDefaultImports } from '../../packages/onda_binaryen_web/src/index.js';

const prefixes = process.argv.slice(2).filter(arg => !arg.startsWith('--'));
async function prepare(prefix) {
  const metadata = JSON.parse(readFileSync(`${prefix}.wasm-metadata.json`));
  const { instance } = await WebAssembly.instantiate(readFileSync(`${prefix}.wasm`), createDefaultImports());
  const { memory, __heap_base, onda_processor_init: init, onda_process: process } = instance.exports;
  let heap = Number(__heap_base.value);
  const alloc = bytes => { heap = (heap + 15) & -16; const result = heap; heap += Math.max(bytes, 1); return result; };
  const params = alloc(metadata.runtime.param_size_bytes);
  const state = alloc(metadata.runtime.state_size_bytes);
  const width = metadata.metadata.outputs[0].scalar === 'f64' ? 8 : 4;
  const out = alloc(128 * width);
  const table = alloc(4);
  if (heap > memory.buffer.byteLength) memory.grow(Math.ceil((heap - memory.buffer.byteLength) / 65536));
  new DataView(memory.buffer).setUint32(table, out, true);
  if (init(params, state, 1, 0, 0, 0, 0, 0)) throw new Error('init failed');
  const run = () => { if (process(state, params, 0, table, 0, 128, 3, 0, 0, 0, 0)) throw new Error('process failed'); };
  const captures = [];
  for (let i = 0; i < 32; i++) { run(); captures.push(Buffer.from(new Uint8Array(memory.buffer, out, 128 * width))); }
  for (let i = 0; i < 2048; i++) run();
  return { prefix, run, captures: Buffer.concat(captures), rounds: [] };
}
const variants = [];
for (const prefix of prefixes) variants.push(await prepare(prefix));
for (const variant of variants) {
  if (!variant.captures.equals(variants[0].captures)) throw new Error(`output differs: ${variant.prefix}`);
}
let iterations = 128;
while (true) {
  const start = performance.now();
  for (let i = 0; i < iterations; i++) variants[0].run();
  if (performance.now() - start > 30) break;
  iterations *= 2;
}
for (let round = 0; round < 9; round++) {
  const order = round % 2 ? [...variants].reverse() : variants;
  for (const variant of order) {
    const start = performance.now();
    for (let i = 0; i < iterations; i++) variant.run();
    variant.rounds.push((performance.now() - start) * 1e6 / (iterations * 128));
  }
}
const median = numbers => [...numbers].sort((a, b) => a - b)[Math.floor(numbers.length / 2)];
const result = variants.map(variant => ({ prefix: variant.prefix, ns_per_frame: median(variant.rounds), rounds: variant.rounds }));
for (const row of result) row.ratio = row.ns_per_frame / result[0].ns_per_frame;
console.log(JSON.stringify({ bitwise_equal_samples: 32 * 128, result }, null, 2));
if (process.argv.includes('--assert-no-regression') && result[1].ratio > 1.02) process.exitCode = 1;
